import {expect} from '@playwright/test';
import {readFileSync} from 'node:fs';
export async function exerciseCollageInteraction(page,info,lang){
 const t=(zh,en)=>lang==='en'?en:zh,dialog=page.getByRole('dialog',{name:t('照片拼图','Photo collage')}),button=(zh,en)=>dialog.getByRole('button',{name:t(zh,en),exact:true}),field=(zh,en)=>dialog.getByLabel(t(zh,en),{exact:true});
 await page.evaluate(()=>{const Original=Worker;window.__collagePreviewProbe={active:0,max:0,count:0};window.Worker=class extends Original{constructor(url,options){super(url,options);this.collage=String(url).includes('collage-worker-');this.pending=new Set();this.addEventListener('message',({data})=>{if(this.pending.delete(data.id))window.__collagePreviewProbe.active--;});}postMessage(data,...rest){if(this.collage&&data.action==='render'){this.pending.add(data.id);const probe=window.__collagePreviewProbe;probe.active++;probe.count++;probe.max=Math.max(probe.max,probe.active);}return super.postMessage(data,...rest);}terminate(){window.__collagePreviewProbe.active-=this.pending.size;this.pending.clear();super.terminate();}};});
 const files=await page.evaluate(async()=>{const result=[];for(const color of ['#174e72','#bc7855']){const c=new OffscreenCanvas(320,200),x=c.getContext('2d');x.fillStyle=color;x.fillRect(0,0,320,200);x.fillStyle='#ffeecc';x.fillRect(20,50,40,70);result.push([...new Uint8Array(await(await c.convertToBlob()).arrayBuffer())]);}return result;});
 await dialog.locator('input[type=file]').first().setInputFiles(files.map((b,i)=>({name:i+'.png',mimeType:'image/png',buffer:Buffer.from(b)})));await expect(dialog.locator('.collage-cells button')).toHaveCount(2);
 // Inspect the actual JSON download payload without repeatedly asking Chrome to download
 // more than ten files in a few seconds. The shared recovery suite exercises real JSON downloads.
 await page.evaluate(()=>{window.__collageSaveCount=0;const create=URL.createObjectURL;URL.createObjectURL=function(blob){if(blob.type==='application/json'){window.__collageSavedBlob=blob;window.__collageSaveCount++;}return create.call(this,blob);};const click=HTMLAnchorElement.prototype.click;HTMLAnchorElement.prototype.click=function(){if(!this.download.endsWith('.pc-collage.json'))click.call(this);};});
 const save=async()=>{const before=await page.evaluate(()=>window.__collageSaveCount);await button('保存布局清单','Save layout document').click();await expect.poll(()=>page.evaluate(()=>window.__collageSaveCount)).toBeGreaterThan(before);return page.evaluate(async()=>JSON.parse(await window.__collageSavedBlob.text()));};
 await field('画布宽度','Canvas width').fill('600');await field('画布高度','Canvas height').fill('400');await field('画布高度','Canvas height').press('Tab');await field('格内缩放','Cell zoom').fill('1.6');const original=await save();
 const cell=i=>dialog.getByRole('button',{name:t('拼图单元格 ','Collage cell ')+(i+1),exact:true});await dialog.evaluate(el=>el.scrollTop=0);const a=await cell(0).boundingBox(),b=await cell(1).boundingBox(),center=r=>({x:r.x+r.width/2,y:r.y+r.height/2}),start=center(a),target=center(b);
 await page.mouse.move(start.x,start.y);await page.mouse.down();await page.mouse.move(target.x,target.y,{steps:6});await expect(cell(1)).toHaveClass(/swap-target/);await page.mouse.up();const swapped=await save();expect(swapped.cells).toEqual([original.cells[1],original.cells[0]]);await expect(field('格内缩放','Cell zoom')).toHaveValue('1.6');await button('撤销拼图','Undo collage').click();expect((await save()).cells).toEqual(original.cells);
 // Continuous input must publish frames before pointer-up, with only one render in flight.
 await dialog.evaluate(el=>el.scrollTop=0);const initialPreview=await dialog.locator('.collage-stage img').getAttribute('src'),beforeFrames=await page.evaluate(()=>window.__collagePreviewProbe.count);let published=0;await page.mouse.move(start.x,start.y);await page.mouse.down();
 for(let i=1;i<=16;i++){await page.mouse.move(start.x+i,start.y+12);await page.evaluate(()=>new Promise(requestAnimationFrame));if(await dialog.locator('.collage-stage img').getAttribute('src')!==initialPreview)published++;}
 expect(published).toBeGreaterThan(0);expect(await page.evaluate(()=>window.__collagePreviewProbe.count)-beforeFrames).toBeGreaterThan(2);await page.mouse.up();expect(await page.evaluate(()=>window.__collagePreviewProbe.max)).toBe(1);await button('撤销拼图','Undo collage').click();
 // Pointer-capture loss cancels the temporary pan; it cannot become an accidental swap.
 await dialog.evaluate(el=>el.scrollTop=0);await page.mouse.move(start.x,start.y);await page.mouse.down();await page.mouse.move(start.x+20,start.y+18);await cell(0).evaluate(el=>el.releasePointerCapture(1));await page.mouse.up();expect((await save()).cells).toEqual(original.cells);
 // Center snap is measured in displayed pixels, independent of canvas output size.
 await dialog.evaluate(el=>el.scrollTop=0);await page.mouse.move(start.x,start.y);await page.mouse.down();await page.mouse.move(start.x+6,start.y+6);await expect(dialog.locator('.collage-guide')).toHaveCount(2);await page.mouse.up();expect((await save()).cells[0].pan).toEqual({x:0,y:0});
 await page.keyboard.down('Shift');await page.mouse.move(start.x,start.y);await page.mouse.down();await page.mouse.move(start.x+6,start.y+6);await expect(dialog.locator('.collage-guide')).toHaveCount(0);await page.mouse.up();await page.keyboard.up('Shift');expect((await save()).cells[0].pan.x).toBeGreaterThan(0);await button('居中照片','Center photo').click();expect((await save()).cells[0]).toMatchObject({pan:{x:0,y:0},zoom:1.6});
 // A burst of trackpad-wheel events is one undo step, even before its idle timer expires.
 await dialog.evaluate(el=>el.scrollTop=0);const beforeWheel=(await save()).cells[0].zoom;
 await cell(0).evaluate(el=>{for(let i=0;i<3;i++)el.dispatchEvent(new WheelEvent('wheel',{deltaY:-10,ctrlKey:true,bubbles:true,cancelable:true}));});await expect.poll(async()=>Number(await field('格内缩放','Cell zoom').inputValue())).toBeGreaterThan(beforeWheel);await button('撤销拼图','Undo collage').click();expect((await save()).cells[0].zoom).toBe(beforeWheel);
 // Real browser touch dispatch exercises two-pointer pinch rather than calling the handler.
 await dialog.evaluate(el=>el.scrollTop=0);const touchBox=await cell(0).boundingBox(),point=center(touchBox),cdp=await page.context().newCDPSession(page);await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:2});
 const touches=distance=>[{id:10,x:point.x-distance,y:point.y},{id:11,x:point.x+distance,y:point.y}];await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:touches(12)});await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:touches(24)});await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:false});await cdp.detach();expect((await save()).cells[0].zoom).toBeCloseTo(beforeWheel*2,5);await button('撤销拼图','Undo collage').click();expect((await save()).cells[0].zoom).toBe(beforeWheel);
 await button('画布比例 16:9','Canvas ratio 16:9').click();await expect(field('画布高度','Canvas height')).toHaveValue('338');await button('拼图长边 1600','Collage long edge 1600').click();expect((await save()).width).toBe(1600);await button('纯黑背景','Black background').click();expect((await save()).background).toBe('#000000');
 await field('格内缩放','Cell zoom').fill('0.5');const img=dialog.locator('.collage-stage img');await expect(img).toHaveJSProperty('naturalWidth',1000);const old=await img.getAttribute('src');await field('显示未填满提示','Show gap guides').uncheck();await expect(img).not.toHaveAttribute('src',old);await expect(dialog.locator('.collage-guide')).toHaveCount(0);
 await field('拼图输出格式','Collage output format').selectOption('jpg');await field('JPEG 质量','JPEG quality').fill('88');const next=page.waitForEvent('download');await button('导出拼图 JPEG','Export collage JPEG').click();const image=await next;expect(image.suggestedFilename()).toBe('Collage.jpg');const data=readFileSync(await image.path());expect([...data.subarray(0,3)]).toEqual([255,216,255]);
 await dialog.evaluate(el=>el.scrollTop=0);await dialog.screenshot({path:info.outputPath('collage-interaction-'+lang+'.png')});if(lang==='en')expect(await dialog.innerText()).not.toMatch(/[\u3400-\u9fff]/);expect(await dialog.evaluate(el=>el.scrollWidth<=el.clientWidth+1)).toBe(true);
 page.once('dialog',d=>d.accept());await button('关闭','Close').click();await expect(dialog).toHaveCount(0);
}
